"""Randomized cross-check: optimized submission engine vs naive reference."""
import json, random, sys
sys.path.insert(0, '/workspace')
sys.path.insert(0, '/workspace/submission')
import ref
from runner import same
from utils import run_request


def gen_run(rng, style='small'):
    if style == 'small':
        M = rng.randint(1, 3); L = rng.randint(1, 2); R = rng.randint(1, 3)
        fcap = rng.randint(1, 12); pcap = rng.randint(1, 12)
        batch = rng.randint(1, 3); period = rng.randint(1, 6)
        neflow = rng.randint(1, 3)
        maxlen = 8
    elif style == 'mid':
        M = rng.randint(1, 5); L = rng.randint(1, 3); R = rng.randint(1, 5)
        fcap = rng.randint(1, 40); pcap = rng.randint(1, 40)
        batch = rng.randint(1, 6); period = rng.randint(1, 12)
        neflow = rng.randint(1, 6)
        maxlen = 20
    else:
        M = rng.randint(1, 16); L = rng.randint(1, 8); R = rng.randint(1, 8)
        fcap = rng.randint(1, 200); pcap = rng.randint(1, 200)
        batch = rng.randint(1, 32); period = rng.randint(1, 40)
        neflow = rng.randint(1, 10)
        maxlen = 60
    U = rng.randint(1, 30)
    borders = sorted(rng.sample(range(1, U), min(R - 1, max(0, U - 1)))) if R > 1 else []
    borders = [0] + borders + [U]
    R = len(borders) - 1
    kind = rng.choice(['fifo', 'sp', 'sff', 'wfq'])
    flows = list(range(neflow))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, rng.randint(0, 8)] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, rng.randint(1, 8)] for f in flows]}
    else:
        policy = {'kind': kind}
    events = []
    ids = iter(range(1000000))
    save_names = []
    nid = 0
    n = rng.randint(0, 60 if style != 'big' else 120)
    for _ in range(n):
        c = rng.random()
        if c < 0.42:
            events.append(['enqueue', nid, rng.choice(flows),
                           rng.randint(1, maxlen), rng.randint(0, 25)])
            nid += 1
        elif c < 0.68:
            events.append(['dequeue', rng.randint(1, 4)])
        elif c < 0.74:
            events.append(['sample'])
        elif c < 0.79:
            nb = rng.randint(1, 4)
            U2 = rng.randint(1, 30)
            bs = sorted(rng.sample(range(1, U2), min(nb - 1, max(0, U2 - 1))))
            events.append(['repartition', [0] + bs + [U2]])
        elif c < 0.85:
            events.append(['cancel', rng.randint(0, nid + 2)])
        elif c < 0.88:
            events.append(['inspect', rng.randint(0, nid + 2)])
        elif c < 0.94:
            if kind == 'wfq':
                events.append(['weight', rng.choice(flows), rng.randint(1, 8)])
            else:
                events.append(['enqueue', nid, rng.choice(flows),
                               rng.randint(1, maxlen), rng.randint(0, 25)])
                nid += 1
        elif c < 0.97:
            name = rng.randint(0, 3)
            events.append(['save', name])
            if name not in save_names:
                save_names.append(name)
        else:
            if save_names:
                events.append(['restore', rng.choice(save_names)])
            else:
                events.append(['save', 0])
                save_names.append(0)
    return {'banks': M, 'load_balancers': L, 'fifo_bytes': fcap,
            'pifo_bytes': pcap, 'refill_batch': batch,
            'sample_period': period, 'borders': borders, 'policy': policy,
            'events': events}


def main():
    seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 300
    styles = ['small', 'mid', 'big']
    bad = 0
    for it in range(count):
        rng = random.Random(seed0 * 100000 + it)
        style = styles[it % 3]
        spec = gen_run(rng, style)
        request = {'runs': [spec]}
        try:
            got = run_request(request)['runs'][0]
        except Exception as exc:
            import traceback; traceback.print_exc()
            print('ENGINE CRASH', it, style); print(json.dumps(spec))
            bad += 1
            if bad > 2: return 1
            continue
        exp = ref.run(spec)
        if not same(got, exp):
            bad += 1
            print('MISMATCH iter', it, 'style', style)
            print(json.dumps(spec))
            for a, b in zip(got['log'], exp['log']):
                if a != b:
                    print('log got ', a); print('log exp ', b); break
            if len(got['log']) != len(exp['log']):
                print('log lengths', len(got['log']), len(exp['log']))
            ga, ea = got['state'], exp['state']
            for key in ga:
                if not same(ga[key], ea[key]):
                    print('state key', key); print('  got', json.dumps(ga[key])[:400])
                    print('  exp', json.dumps(ea[key])[:400])
            if bad > 2:
                return 1
    print('fuzz done:', count, 'cases,', bad, 'mismatches')
    return 1 if bad else 0


sys.exit(main())
